#pragma once
#include "model.hpp"
#include "transport_display.hpp"
namespace vamp {
struct RulerLabel{double beat;std::wstring text;};
struct PlaylistRuler{double labelStep=4,gridStep=1;std::vector<RulerLabel>labels;};
inline PlaylistRuler playlistRuler(double start,double span,double width,double snap){PlaylistRuler out;if(!std::isfinite(start)||!std::isfinite(span)||!std::isfinite(width)||span<=0||width<=0)return out;double pixels=width/span;out.labelStep=1./16;while(out.labelStep*pixels<72&&out.labelStep<4096)out.labelStep*=2;out.gridStep=std::max(1./128,std::min(snap,out.labelStep));while(out.gridStep*pixels<10)out.gridStep*=2;int count=std::min(4096,(int)std::ceil(span/out.labelStep)+1);double first=std::ceil((start-1e-7)/out.labelStep)*out.labelStep;for(int i=0;i<count;i++){double beat=first+i*out.labelStep;if(beat>start+span+1e-7)break;auto digits=transportDigits(beat);auto text=digits[0];if(out.labelStep<4)text+=L"."+digits[1];if(out.labelStep<1)text+=L"."+digits[2];out.labels.push_back({beat,text});}return out;}
inline PlaylistRuler playlistRuler(double start,double span,double width,double snap,const TempoMap&clock){auto out=playlistRuler(start,span,width,snap);out.labels.clear();double step=out.labelStep;double first=clock.barStart(start);auto meter=clock.meterAt(first);double bar=meter.numerator*4./meter.denominator;if(step>=bar){int stride=std::max(1,(int)std::ceil(step/bar));for(int n=0;n<8192&&first<=start+span+1e-7;n++){auto m=clock.meterAt(first);double length=m.numerator*4./m.denominator;if(first>=start-1e-7&&((clock.musical(first).bar-1)%stride==0||std::abs(first-m.beat)<1e-7))out.labels.push_back({first,std::to_wstring(clock.musical(first).bar)});double next=first+length;auto change=clock.nextChange(first);if(change>first+1e-7&&change<next&&std::abs(clock.meterAt(change).beat-change)<1e-7)next=change;first=next;}}else for(double b=std::ceil((start-1e-7)/step)*step;b<=start+span+1e-7&&out.labels.size()<4096;b+=step){auto p=clock.musical(b);auto text=std::to_wstring(p.bar)+L"."+std::to_wstring(p.beat);if(step<4./clock.meterAt(b).denominator){auto tick=std::to_wstring(p.tick/10);if(tick.size()<2)tick=L"0"+tick;text+=L"."+tick;}out.labels.push_back({b,text});}return out;}
}
